fn main() {
    // Explicit application manifest: `asInvoker`, `uiAccess="false"` (KeySwitch never elevates
    // and never asks for UI access), Common Controls v6, per-monitor DPI awareness.
    // The version resource (FileVersion, ProductVersion, ProductName, FileDescription) is
    // generated by tauri-build from `tauri.conf.json` and the package metadata.
    let windows = tauri_build::WindowsAttributes::new()
        .app_manifest(include_str!("windows-app-manifest.xml"));
    let attributes = tauri_build::Attributes::new().windows_attributes(windows);
    tauri_build::try_build(attributes).expect("failed to run tauri-build");
}
